 CREATE OR REPLACE FUNCTION public.providersanctionenddatenotification()                                                                                                                                                                                                                                  
  RETURNS character varying                                                                                                                                                                                                                                                                               
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                        
 AS $function$                                                                                                                                                                                                                                                                                            
 DECLARE                                                                                                                                                                                                                                                                                                  
 v_activity  record;                                                                                                                                                                                                                                                                                      
 v_msg character varying;                                                                                                                                                                                                                                                                                 
 v_status character varying;                                                                                                                                                                                                                                                                              
 v_status1 character varying;                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                          
 BEGIN                                                                                                                                                                                                                                                                                                    
 /* Provider - 7 days before expiration date of the sanction end day, a notification should be sent to the supervisor */                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                          
 FOR  v_activity  in                                                                                                                                                                                                                                                                                      
 select distinct coalesce(UP.lastname,'')||', '|| coalesce(UP.firstname,'') as fromuser , pls.create_user_id as fromsecurityusersid , tma1.securityusersid as tosecurityusersid , pls.license_no , pls.license_sanction_type , pls.limitation_type, pls.sanction_end_dt  from providerlicensesanctions pls
 JOIN userprofile as UP                                                                                                                                                                                                                                                                                   
            ON UP.securityusersid = pls.create_user_id and UP.activeflag = 1                                                                                                                                                                                                                              
            join teammemberassignment tma on tma.securityusersid = pls.create_user_id                                                                                                                                                                                                                     
    join teammember tm                                                                                                                                                                                                                                                                                    
                 ON tm.teammemberid = tma.teammemberid  AND tm.activeflag= 1                                                                                                                                                                                                                              
              join routingconfig rc                                                                                                                                                                                                                                                                       
                 ON rc.sourcerolekey = tm.roletypekey   AND rc.activeflag= 1                                                                                                                                                                                                                              
                 and rc.eventcode = 'PTA'                                                                                                                                                                                                                                                                 
                  join teammember tm1                                                                                                                                                                                                                                                                     
                 ON tm1.roletypekey = rc.targetrolekey AND tm.activeflag= 1                                                                                                                                                                                                                               
                  join teammemberassignment tma1                                                                                                                                                                                                                                                          
                 on tm1.teammemberid = tma1.teammemberid                                                                                                                                                                                                                                                  
 WHERE pls.sanction_end_dt::date - now()::date <= 7                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                                                          
 LOOP                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                          
 -- Limitation# is due to expire within 7 days. Please act before sanction end date.                                                                                                                                                                                                                      
 v_msg:=   'Limitation of '|| v_activity.limitation_type :: character varying ||' for the license number ('|| v_activity.license_no ||') is due to expire in 7 days. Please act before'  || v_activity.sanction_end_dt :: date ||'.';                                                                     
                                                                                                                                                                                                                                                                                                          
 SELECT send_notification INTO v_status FROM send_notification(v_activity.tosecurityusersid, v_activity.fromsecurityusersid, v_activity.tosecurityusersid,                                                                                                                                                
 'System', 'High', v_msg, v_msg , v_activity.license_no::character varying);                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                          
 SELECT send_notification INTO v_status1 FROM send_notification(v_activity.fromsecurityusersid, v_activity.fromsecurityusersid, v_activity.fromsecurityusersid,                                                                                                                                           
 'System', 'High', v_msg, v_msg , v_activity.license_no::character varying);                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                          
 END  LOOP;                                                                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                                                          
 return 'Success';                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                          
 END;                                                                                                                                                                                                                                                                                                     
 $function$                                                                                                                                                                                                                                                                                               

